{
    "name": "typesense/laravel-scout-typesense-driver",
    "description": "Laravel Scout Driver for Typesense",
    "keywords": [
        "laravel",
        "typesense",
        "search"
    ],
    "type": "library",
    "homepage": "https://typesense.org",
    "license": "MIT",
    "authors": [
        {
            "name": "Abdullah Al-Faqeir",
            "email": "abdullah@devloops.net",
            "homepage": "https://www.devloops.net",
            "role": "Developer"
        },
        {
            "name": "hi019",
            "homepage": "https://github.com/hi019",
            "role": "Developer"
        }
    ],
    "minimum-stability": "stable",
    "autoload": {
        "psr-4": {
            "Typesense\\LaravelTypesense\\": "src/",
            "Typesense\\LaravelTypesense\\Tests\\": "tests/"
        }
    },
    "extra": {
        "laravel": {
            "providers": [
                "Typesense\\LaravelTypesense\\TypesenseServiceProvider"
            ],
            "aliases": {
                "Typesense": "Typesense\\LaravelTypesense\\TypesenseFacade"
            }
        }
    },
    "require": {
        "php": "^8.0",
        "laravel/scout": "^10.0|^11.0|^12.0",
        "illuminate/bus": "^10.0|^11.0|^12.0",
        "illuminate/contracts": "^10.0|^11.0|^12.0",
        "illuminate/database": "^10.0|^11.0|^12.0",
        "illuminate/pagination": "^10.0|^11.0|^12.0",
        "illuminate/queue": "^10.0|^11.0|^12.0",
        "illuminate/support": "^10.0|^11.0|^12.0",
        "typesense/typesense-php": "^6.1.0-RC2"
    },
    "config": {
        "allow-plugins": {
            "pestphp/pest-plugin": true,
            "php-http/discovery": true
        }
    },
    "suggest": {
        "typesense/typesense-php": "Required to use the Typesense php client."
    },
    "require-dev": {
        "phpunit/phpunit": "^8.0|^9.0|^10.5|^11.5|^12.5|^13.2",
        "mockery/mockery": "^1.6",
        "orchestra/testbench": "^8.36|^9.15|^10.8|^11.1",
        "symfony/http-client": "^5.4|^7.0|^8.1"
    },
    "prefer-stable": true
}
